<?php
spl_autoload_register(function($c){if(strpos($c,'app\\')===0){$p=__DIR__.'/../../src/core/application/'.str_replace('\\','/',substr($c,4)).'.php';if(is_file($p))require_once $p;}});
$base='http://127.0.0.1:18983';
$cfg=array('cloudflare'=>array('token'=>'test-token','endpoint'=>$base.'/cloudflare'),'dnsla'=>array('api_id'=>'test-id','api_secret'=>'test-secret','endpoint'=>$base.'/dnsla'),'namesilo'=>array('api_key'=>'test-key','endpoint'=>$base.'/namesilo'),'godaddy'=>array('key'=>'test-key','secret'=>'test-secret','env'=>'production','endpoint'=>$base.'/godaddy'));
$ok=true; foreach($cfg as $code=>$c){try{$d=\app\common\dns\DnsFactory::make($code,$c);$d->check();$z=$d->getDomains();if(!$z||$z[0]['domain']!=='example.com')throw new Exception('zone');$id=$z[0]['id'];$a=$d->addRecord('example.com',$id,'abc','A','1.2.3.4','default',600);$t=$d->addRecord('example.com',$id,'abc','TXT','hello world');$cn=$d->addRecord('example.com',$id,'www.abc','CNAME','target.example.net');$r=$d->getRecords('example.com',$id,'abc');if(count($r)!==3)throw new Exception('records');$d->updateRecord('example.com',$id,$a,'abc','A','5.6.7.8');$d->deleteRecord('example.com',$id,$a);$d->deleteRecord('example.com',$id,$t);$d->deleteRecord('example.com',$id,$cn);$d->getLines();echo $code." PASS\n";}catch(Exception $e){$ok=false;echo $code.' FAIL: '.$e->getMessage()."\n";}}
exit($ok?0:1);
